package com.asmj.marketplace.category.controller; import com.asmj.marketplace.category.model.Category; import com.asmj.marketplace.category.service.CategoryService; import com.asmj.marketplace.common.response.ApiResponse; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/categories") @RequiredArgsConstructor public class CategoryController {private final CategoryService s;@GetMapping public ApiResponse<List<Category>> all(){return ApiResponse.ok("Categories",s.all());}@PostMapping @PreAuthorize("hasRole('ADMIN')") public ApiResponse<Category> add(@RequestBody Category c){return ApiResponse.ok("Created",s.save(c));}@PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<Category> update(@PathVariable String id,@RequestBody Category c){return ApiResponse.ok("Updated",s.update(id,c));}@DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<Void> delete(@PathVariable String id){s.delete(id);return ApiResponse.ok("Deleted",null);}}
